$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot; $prep=Join-Path $root 'prepare-intervention.ps1'; $transport=Join-Path $root 'github-transport.ps1'; $worktree=(Resolve-Path (Join-Path $root '..\..')).Path; $out=Join-Path $env:TEMP ('flcad-ab03-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Force -Path $out|Out-Null
function Assert-True([bool]$Condition,[string]$Message){if(!$Condition){throw "ASSERTION FAILED: $Message"}}
try {
  $base=@('-NoProfile','-File',$prep,'-TaskId','AB-03-DEMO','-Event','USER_APPROVAL_REQUIRED','-Reason','Human review required','-Priority','P1','-ActionRequested','Review acceptance criteria','-TechnicalSummary','Controlled intervention test','-ReportReference','outbox/AB-01-DRYRUN-ENV/report.json','-Worktree',$worktree,'-DeduplicationId','AB-03-DEMO-APPROVAL','-ExecutionMode','HEADLESS_DEVELOPMENT','-OutDir',$out)
  $first=& powershell @base|ConvertFrom-Json; Assert-True ($first.status -eq 'prepared-for-publication') 'intervention must be prepared'; $int=Get-Content (Join-Path $out 'AB-03-DEMO-APPROVAL.json') -Raw|ConvertFrom-Json; Assert-True ($int.state -eq 'WAITING_FOR_USER') 'state must wait for user'
  $second=& powershell @base|ConvertFrom-Json; Assert-True ($second.status -eq 'deduplicated') 'event must be deduplicated'
  $bad=$base.Clone(); $bad[$bad.IndexOf('USER_APPROVAL_REQUIRED')]='IMPLEMENTATION_COMPLETED'; $old=$ErrorActionPreference;$ErrorActionPreference='Continue';& powershell @bad 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;Assert-True($code -ne 0)'informational event must be rejected'
  $blocked=$base.Clone();$blocked[$blocked.IndexOf('AB-03-DEMO')]='AB-03-BLOCKED';$blocked[$blocked.IndexOf('USER_APPROVAL_REQUIRED')]='AGENT_BLOCKED';$blocked[$blocked.IndexOf('AB-03-DEMO-APPROVAL')]='AB-03-BLOCKED-KEY';$blocked[$blocked.IndexOf('Review acceptance criteria')]='Wait for external decision';& powershell @blocked|Out-Null; $blockedObj=Get-Content (Join-Path $out 'AB-03-BLOCKED-KEY.json') -Raw|ConvertFrom-Json;Assert-True($blockedObj.state -eq 'BLOCKED')'AGENT_BLOCKED must be BLOCKED'
  $gui=$base.Clone();$gui[$gui.IndexOf('AB-03-DEMO')]='AB-03-GUI';$gui[$gui.IndexOf('AB-03-DEMO-APPROVAL')]='AB-03-GUI-KEY';$gui[$gui.IndexOf('HEADLESS_DEVELOPMENT')]='GUI_TEST_REQUESTED';& powershell @gui|Out-Null;$guiObj=Get-Content (Join-Path $out 'AB-03-GUI-KEY.json') -Raw|ConvertFrom-Json;Assert-True($guiObj.gui_control_authorization -eq 'not-granted')'GUI must remain unauthorized'
  $mal=$base.Clone();$mal[$mal.IndexOf('AB-03-DEMO')]='AB-03-MAL';$mal[$mal.IndexOf('AB-03-DEMO-APPROVAL')]='AB-03-MAL-KEY';$mal[$mal.IndexOf('Review acceptance criteria')]='Send token=DO_NOT_EXPORT';$old=$ErrorActionPreference;$ErrorActionPreference='Continue';& powershell @mal 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;Assert-True($code -ne 0)'secret must be rejected'
  $handled=@('-NoProfile','-File',$prep,'-TaskId','AB-03-DEMO','-Event','USER_APPROVAL_REQUIRED','-Reason','Human review required','-Priority','P1','-ActionRequested','Review acceptance criteria','-TechnicalSummary','Controlled intervention test','-ReportReference','outbox/AB-01-DRYRUN-ENV/report.json','-Worktree',$worktree,'-DeduplicationId','AB-03-DEMO-APPROVAL','-OutDir',$out,'-MarkHandled','-HandledBy','operator','-Resolution','Review recorded');$handledResult=& powershell @handled|ConvertFrom-Json;Assert-True($handledResult.status -eq 'handled')'handling must be recorded'
  $transportResult=& powershell -NoProfile -File $transport -Intervention (Join-Path $out 'AB-03-BLOCKED-KEY.json') -Worktree $worktree -OutDir $out -SimulatePublication|ConvertFrom-Json;Assert-True($transportResult.publish_performed -eq $false)'simulation cannot publish';Assert-True($transportResult.write_permission -eq 'not-verified')'permission must remain unverified';Assert-True(Test-Path (Join-Path $out 'AB-03-BLOCKED-KEY-github.json'))'GitHub envelope must exist'
  Write-Output 'intervention.tests.ps1: PASS'
} finally {Remove-Item -LiteralPath $out -Recurse -Force -ErrorAction SilentlyContinue}
